// .lighthouserc-mobile-full.cjs
// Mobile full-site Lighthouse CI config for weekly audit
// URLs are dynamically generated by scripts/generate-lighthouse-urls.cjs

const fs = require('fs');
const path = require('path');

let urls;
try {
  urls = JSON.parse(
    fs.readFileSync(path.join(__dirname, '.lighthouse-urls.json'), 'utf8')
  );
} catch {
  // Fallback to minimal set if URL generation hasn't run
  urls = ['http://localhost:8788/en/', 'http://localhost:8788/fr/'];
}

module.exports = {
  ci: {
    collect: {
      startServerCommand: 'npx wrangler dev --port 8788',
      startServerReadyPattern: 'Ready on',
      startServerReadyTimeout: 30000,
      url: urls,
      numberOfRuns: 1, // Single run for speed on 40+ URLs
      settings: {
        chromeFlags: '--no-sandbox --disable-dev-shm-usage',
        // No preset = Lighthouse mobile default (4x CPU throttle, simulated slow 4G)
      },
    },
    assert: {
      assertions: {
        // Warn on everything (weekly audit is informational, not gating)
        'categories:seo': ['warn', { minScore: 0.9 }],
        'categories:accessibility': ['warn', { minScore: 0.9 }],
        'categories:performance': ['warn', { minScore: 0.75 }],
        'categories:best-practices': ['warn', { minScore: 0.75 }],

        'is-crawlable': 'off',
        'uses-long-cache-ttl': 'off',
        'redirects-http': 'off',
        'csp-xss': 'off',
      },
    },
    upload: {
      target: 'temporary-public-storage',
    },
  },
};
